mapper.select:
SELECT AVG(score) AS avgScore, COUNT(1) AS reviewCount
FROM mall_product_review
WHERE product_id = #{productId}

SELECT r.review_id, r.order_id, r.product_id, r.member_id, r.score, r.content, r.images, r.create_time, m.nick_name AS member_nickname, p.name AS product_name FROM mall_product_review r LEFT JOIN mall_member m ON m.member_id = r.member_id LEFT JOIN mall_product p ON p.product_id = r.product_id
AND r.product_id = #{productId} AND r.member_id = #{memberId}
ORDER BY r.create_time DESC
